/* ============================================================
   DOI_PROD_SUBUL  ←  202608 엑셀 적재
   DB : 도우제조원가시스템 (10.100.40.17,14233)
   행 : 59행
   엑셀: 08월 재고수불부(260910).xlsx / 시트 '재고금액'(재공품수불) R4~ (합계행 제외)
   * 컬럼은 헤더 라벨 기준 매핑. 8월 헤더에 '기타출고(폐기)'가 신규 추가되어
     7월 기준 열 위치를 그대로 쓰면 오른쪽 전체가 한 칸 밀림.
     (해당 값은 전행 0이고 대응 DB 컬럼이 없어 무시)
   구분: 작업구분='P' 또는 도우모델이 P로 끝나면 '양산' (VN034P1/2/3 대응)
   실행: 검증 통과 시 자동 COMMIT, 실패 시 자동 ROLLBACK
   ============================================================ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

DECLARE @before INT = (SELECT COUNT(*) FROM [DOI_PROD_SUBUL] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL');
DELETE FROM [DOI_PROD_SUBUL] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL';


/* ---------- 검증 ---------- */
DECLARE @ok BIT = 1, @msg NVARCHAR(2000) = N'';
DECLARE @after INT = (SELECT COUNT(*) FROM [DOI_PROD_SUBUL] WHERE [YYYYMM]='202608' AND [SITE]='HQ' AND [SEL_CODE]='ACTUAL');
IF @after <> 59 BEGIN SET @ok=0; SET @msg=@msg+N'행수 59 기대, 실제 '+CAST(@after AS NVARCHAR(20))+N'; '; END
IF ABS(ISNULL((SELECT SUM(BOH_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) - 82876) > 1 BEGIN SET @ok=0; SET @msg=@msg+N'기초합계 불일치(기대 82876, 실제 '+CAST(ISNULL((SELECT SUM(BOH_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(IN_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) - 387490) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'입고합계 불일치(기대 387490, 실제 '+CAST(ISNULL((SELECT SUM(IN_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(OUT_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) - 360616) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'출고합계 불일치(기대 360616, 실제 '+CAST(ISNULL((SELECT SUM(OUT_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(LOSS_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) - 65906) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'LOSS합계 불일치(기대 65906, 실제 '+CAST(ISNULL((SELECT SUM(LOSS_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT SUM(EOH_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) - 44102) > 1 BEGIN SET @ok=0; SET @msg=@msg+N'재고합계 불일치(기대 44102, 실제 '+CAST(ISNULL((SELECT SUM(EOH_MONTH) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608'),0) AS NVARCHAR(40))+N'); '; END
IF ABS(ISNULL((SELECT COUNT(*) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608' AND 구분=N'양산'),0) - 14) > 0 BEGIN SET @ok=0; SET @msg=@msg+N'양산행수 불일치(기대 14, 실제 '+CAST(ISNULL((SELECT COUNT(*) FROM DOI_PROD_SUBUL WHERE YYYYMM='202608' AND 구분=N'양산'),0) AS NVARCHAR(40))+N'); '; END

IF @ok = 1
BEGIN
  COMMIT;
  SELECT N'DOI_PROD_SUBUL 적재 완료' AS 결과, @before AS 삭제전행수, @after AS 적재행수;
END
ELSE
BEGIN
  ROLLBACK;
  SELECT N'DOI_PROD_SUBUL 검증 실패 — 원상복구' AS 결과, @msg AS 사유;
END
GO